// ===== app.js part 2 =====

async function detectStage(imp){app.innerHTML=`${stepper(5)}<section class="card"><h1>Detect MCQs</h1><p>The TXT was explicitly approved. Detection is now available. Nothing will be added to the library automatically.</p><div class="row"><button id="detect">Run MCQ detection</button><button id="backTxt" class="secondary">Back to TXT</button></div></section>`;$('#backTxt').onclick=async()=>{imp.stage='EXTRACTED';await put('imports',imp);render()};$('#detect').onclick=async()=>{const parsed=parseMCQs(imp.txt,{sourceName:imp.sourceName,sourceFilename:imp.sourceFilename});imp.candidates=parsed.candidates;imp.rejected=parsed.rejected;imp.counts=parsed.counts;imp.stage='PARSED';await put('imports',imp);render();};}

async function reviewStage(imp){
 const c=imp.candidates||[], counts=imp.counts||{};
 app.innerHTML=`${stepper(6)}<section class="card"><h1>MCQ Review</h1><div class="grid"><div><b>Questions detected</b><div class="stat">${counts.detected||0}</div></div><div><b>Ready</b><div class="stat">${counts.ready||0}</div></div><div><b>Needs review</b><div class="stat">${counts.review||0}</div></div><div><b>Rejected as non-MCQ</b><div class="stat">${counts.rejected||0}</div></div></div><p class="notice">A question is not approved merely because the parser called it READY. Every question needs an explicit human approval.</p><div class="row"><button id="approveAllReady">Approve all READY</button><button id="continueApprove" disabled>Continue to final approval</button></div></section><section class="card"><h2>Detected candidates</h2><div id="cand"></div></section><section class="card"><details><summary>Rejected / questionable diagnostics</summary><div id="rej"></div></details></section>`;
 const draw=()=>{
   const wrap=$('#cand'); wrap.innerHTML='';
   imp.candidates.forEach(x=>wrap.append(renderCandidate(x,{
     approve:async id=>{const q=imp.candidates.find(z=>z.id===id);if(q){q.approved=true;await put('imports',imp);await reviewStage(imp);}},
     edit:id=>editCandidate(imp,id),
     reject:async id=>{if(!confirm('Remove this candidate? This is an explicit rejection and will be recorded.'))return;const q=imp.candidates.find(z=>z.id===id);if(q){q.status='REJECTED AS NON-MCQ';q.approved=false;q.diagnostic=(q.diagnostic||'')+' | User rejected/deleted this candidate.';imp.counts.rejected=(imp.counts.rejected||0)+1;imp.counts.review=Math.max(0,(imp.counts.review||0)-1);await put('imports',imp);await reviewStage(imp);}}
   })));
   const r=$('#rej'); r.innerHTML=(imp.rejected||[]).map(x=>`<div class="question"><span class="pill rejected">REJECTED AS NON-MCQ</span><p>${esc(x.rawText)}</p><p class="small">${esc(x.diagnostic)}</p></div>`).join('')||'<p class="muted">No parser rejections.</p>';
   const can=imp.candidates.filter(x=>x.status!=='REJECTED AS NON-MCQ').every(x=>x.approved); $('#continueApprove').disabled=!can;
 };
 draw();
 $('#approveAllReady').onclick=async()=>{imp.candidates.forEach(x=>{if(x.status==='READY')x.approved=true});await put('imports',imp);await reviewStage(imp);};
 $('#continueApprove').onclick=async()=>{if(!imp.candidates.filter(x=>x.status!=='REJECTED AS NON-MCQ').every(x=>x.approved))return;imp.approvedQuestions=imp.candidates.filter(x=>x.approved).map(normalizeQ);imp.stage='APPROVED';imp.finalApprovedAt=new Date().toISOString();await put('imports',imp);render();};
}
function normalizeQ(q){return {id:q.id,question:q.question,options:{...q.options},correctAnswer:q.correctAnswer,displayedNumber:q.displayedNumber,sourcePage:q.sourcePage,sourceLine:q.sourceLine};}
async function editCandidate(imp,id){const idx=imp.candidates.findIndex(x=>x.id===id);state.editIndex=idx;const q=imp.candidates[idx];app.innerHTML=`${stepper(6)}<section class="card"><h1>Edit MCQ</h1><p class="muted">Question ID: ${esc(q.id)} · displayed number: ${esc(q.displayedNumber??'—')}</p><label>Question<textarea id="eq" style="min-height:150px">${esc(q.question)}</textarea></label><div class="grid">${['A','B','C','D'].map(k=>`<label>Option ${k}<textarea id="e${k}" style="min-height:100px">${esc(q.options[k]||'')}</textarea></label>`).join('')}</div><label>Correct answer<select id="ea"><option value="">Choose…</option>${['A','B','C','D'].map(k=>`<option ${q.correctAnswer===k?'selected':''}>${k}</option>`).join('')}</select></label><p class="small">Status: ${esc(q.status)} · ${esc(q.diagnostic||'')}</p><div class="row"><button id="prev" class="secondary">Previous</button><button id="save">Save</button><button id="ready">Save as ready</button><button id="next">Next</button><button id="delete" class="danger">Delete</button></div></section>`;const save=async ready=>{q.question=$('#eq').value;q.options={A:$('#eA').value,B:$('#eB').value,C:$('#eC').value,D:$('#eD').value};q.correctAnswer=$('#ea').value||null;const complete=validateApprovedQuestions([q]);q.status=complete?'READY':'REVIEW';q.diagnostic=complete?'Manually validated.':'Still incomplete or missing correct answer.';q.approved=ready&&complete;imp.counts.ready=imp.candidates.filter(x=>x.status==='READY').length;imp.counts.review=imp.candidates.filter(x=>x.status==='REVIEW').length;await put('imports',imp);return complete};$('#save').onclick=async()=>{await save(false);reviewStage(imp)};$('#ready').onclick=async()=>{await save(true);reviewStage(imp)};$('#prev').onclick=async()=>{await save(false);state.editIndex=Math.max(0,state.editIndex-1);editCandidate(imp,imp.candidates[state.editIndex].id)};$('#next').onclick=async()=>{await save(false);state.editIndex=Math.min(imp.candidates.length-1,state.editIndex+1);editCandidate(imp,imp.candidates[state.editIndex].id)};$('#delete').onclick=async()=>{if(confirm('Delete this candidate?')){q.status='REJECTED AS NON-MCQ';q.approved=false;q.diagnostic=(q.diagnostic||'')+' | User rejected/deleted this candidate.';await put('imports',imp);reviewStage(imp)}};}

async function jsonStage(imp){const qs=imp.approvedQuestions||[];const obj={quizName:imp.sourceName,sourceFilename:imp.sourceFilename,importMetadata:{importId:imp.id,createdAt:imp.createdAt,txtApprovedAt:imp.txtApprovedAt,finalApprovedAt:imp.finalApprovedAt},sourceTxt:imp.txt,questions:qs};app.innerHTML=`${stepper(8)}<section class="card"><h1>Generate JSON</h1><p>All included questions were explicitly approved. This JSON is the quiz data source.</p><div class="code">${esc(JSON.stringify(obj,null,2).slice(0,12000))}${JSON.stringify(obj).length>12000?'\n…':''}</div><div class="row"><button id="download">Download JSON</button><button id="add">Add to Library</button></div></section>`;$('#download').onclick=()=>downloadJSON(obj,imp.sourceName);$('#add').onclick=async()=>{const quiz={id:'quiz_'+Date.now().toString(36),name:imp.sourceName,sourceFilename:imp.sourceFilename,createdAt:new Date().toISOString(),questions:qs,progress:{currentIndex:0,answered:0},sourceImportId:imp.id};await put('quizzes',quiz);imp.quizId=quiz.id;imp.stage='ADDED';await put('imports',imp);render()};}
async function addedStage(imp){app.innerHTML=`${stepper(9)}<section class="card center"><h1>Added to Library</h1><p><b>${esc(imp.sourceName)}</b> is now a separate local quiz source.</p><div class="row" style="justify-content:center"><button id="lib">Open Library</button><button id="home">Home</button></div></section>`;$('#lib').onclick=()=>go('library');$('#home').onclick=()=>go('home');}

async function library(){const qs=await all('quizzes');app.innerHTML=`<section class="card"><h1>Quiz Library</h1><p class="muted">Each imported source stays separate.</p></section>${qs.map(q=>`<section class="card"><h2>${esc(q.name)}</h2><p>${q.questions.length} questions · ${q.progress?.currentIndex||0}/${q.questions.length} position</p><div class="progressbar"><div style="width:${Math.min(100,((q.progress?.currentIndex||0)/q.questions.length)*100)}%"></div></div><div class="row" style="margin-top:10px"><button data-play="${q.id}">${(q.progress?.currentIndex||0)>=q.questions.length?'Restart':'Resume'}</button><button class="danger" data-del="${q.id}">Delete quiz</button></div></section>`).join('')||'<section class="card"><p>No quizzes yet.</p></section>'}`;document.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>startQuiz(b.dataset.play,'library'));document.querySelectorAll('[data-del]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this quiz and its progress? The original import source remains in Imports.')){const q=await get('quizzes',b.dataset.del);await del('quizzes',q.id);const ps=await all('progress');for(const p of ps)if(p.quizId===q.id)await del('progress',p.id);library()}});}

async function startQuiz(id,mode){state.quizId=id;state.quizMode=mode;await renderQuiz();}
async function renderQuiz(){const q=await get('quizzes',state.quizId);if(!q)return go('library');const idx=Math.min(q.progress?.currentIndex||0,q.questions.length-1);const question=q.questions[idx];if(!question){app.innerHTML=`<section class="card center"><h1>Finished</h1><button id="back">Back to Library</button></section>`;$('#back').onclick=()=>go('library');return;}app.innerHTML=`<section class="card"><div class="row" style="justify-content:space-between"><b>${esc(q.name)}</b><span>${idx+1} / ${q.questions.length}</span></div><div class="progressbar"><div style="width:${((idx)/q.questions.length)*100}%"></div></div><h2>${esc(question.question)}</h2>${['A','B','C','D'].map(k=>`<button class="option" data-opt="${k}" style="width:100%;text-align:left;color:#18212f;background:#f4f6f9">${k}. ${esc(question.options[k])}</button>`).join('')}<div id="feedback"></div></section>`;document.querySelectorAll('[data-opt]').forEach(b=>b.onclick=async()=>{document.querySelectorAll('[data-opt]').forEach(x=>x.disabled=true);const correct=b.dataset.opt===question.correctAnswer;$('#feedback').innerHTML=`<p class="${correct?'success':'danger-text'}"><b>${correct?'Correct':'Incorrect'}</b> · correct answer: ${question.correctAnswer}</p><button id="nextQ">${idx+1<q.questions.length?'Next question':'Finish'}</button>`;await recordAnswer(q,question,correct);$('#nextQ').onclick=()=>renderQuiz();});}

async function wrong(){const items=await getWrongQuestions();app.innerHTML=`<section class="card"><h1>Wrong Answers</h1><p>These stay tied to their original quiz. Correct retries remove them from the wrong pile.</p></section><section class="card"><h2>ALL WRONG ANSWERS</h2><div id="wrongList"></div></section>`;const w=$('#wrongList');if(!items.length){w.innerHTML='<p class="success">No wrong answers. Humanity survives another day.</p>';return;}items.forEach(item=>{const el=document.createElement('div');el.className='question';el.innerHTML=`<span class="pill review">${esc(item.quiz.name)}</span><h3>${esc(item.question.question)}</h3>${['A','B','C','D'].map(k=>`<div class="option"><b>${k}.</b> ${esc(item.question.options[k])}</div>`).join('')}<button>Retry</button>`;el.querySelector('button').onclick=()=>retryWrong(item);w.append(el)});}
async function retryWrong(item){const q=JSON.parse(JSON.stringify(item.quiz));const question=item.question;app.innerHTML=`<section class="card"><h1>Retry</h1><p class="muted">${esc(q.name)}</p><h2>${esc(question.question)}</h2>${['A','B','C','D'].map(k=>`<button class="option" data-r="${k}" style="width:100%;text-align:left;color:#18212f;background:#f4f6f9">${k}. ${esc(question.options[k])}</button>`).join('')}<div id="fb"></div></section>`;document.querySelectorAll('[data-r]').forEach(b=>b.onclick=async()=>{document.querySelectorAll('[data-r]').forEach(x=>x.disabled=true);const ok=b.dataset.r===question.correctAnswer;await recordAnswer(q,question,ok,{advance:false});$('#fb').innerHTML=`<p class="${ok?'success':'danger-text'}"><b>${ok?'Correct. Removed from wrong pile.':'Still incorrect. It remains in the wrong pile.'}</b></p><button id="backw">Back</button>`;$('#backw').onclick=()=>go('wrong');});}

async function daily(){const count=Number(localStorage.getItem('dailyCount')||10);const paper=await getDailyPaper(count);const quizzes=await all('quizzes');app.innerHTML=`<section class="card"><h1>Daily Paper</h1><p>Persistent for ${esc(paper.date)} · selection is saved for the day.</p><div class="row">${[10,15,20,25].map(n=>`<button data-count="${n}" class="${n===count?'':'secondary'}">${n} questions</button>`).join('')}</div></section><section class="card"><div id="dailyList"></div></section>`;[10,15,20,25].forEach(n=>{const b=document.querySelector(`[data-count="${n}"]`);b.onclick=()=>{localStorage.setItem('dailyCount',n);daily()}});const list=$('#dailyList');paper.items.forEach((it,i)=>{const q=quizzes.find(x=>x.id===it.quizId);const question=q?.questions.find(x=>x.id===it.questionId);if(!question)return;const el=document.createElement('div');el.className='question';el.innerHTML=`<div class="muted small">${i+1}. ${esc(q.name)}</div><h3>${esc(question.question)}</h3>${['A','B','C','D'].map(k=>`<button class="option" data-d="${it.quizId}:${it.questionId}:${k}" style="width:100%;text-align:left;color:#18212f;background:#f4f6f9">${k}. ${esc(question.options[k])}</button>`).join('')}<div class="df"></div>`;el.querySelectorAll('[data-d]').forEach(b=>b.onclick=async()=>{el.querySelectorAll('[data-d]').forEach(x=>x.disabled=true);const key=b.dataset.d.split(':');const ok=key[2]===question.correctAnswer;await recordAnswer(q,question,ok,{advance:false});el.querySelector('.df').innerHTML=`<p class="${ok?'success':'danger-text'}">${ok?'Correct':'Incorrect'} · answer ${question.correctAnswer}</p>`});list.append(el)});
}
async function review(){const [qs,ps]=await Promise.all([all('quizzes'),all('progress')]);const due=[];for(const q of qs)for(const x of q.questions){const p=ps.find(z=>z.quizId===q.id&&z.questionId===x.id);if(isDue(p))due.push({q,x})}app.innerHTML=`<section class="card"><h1>Review</h1><p>Due questions are selected from all quizzes.</p></section><section class="card">${due.slice(0,50).map((a,i)=>`<div class="question"><span class="pill">${esc(a.q.name)}</span><h3>${i+1}. ${esc(a.x.question)}</h3>${['A','B','C','D'].map(k=>`<div class="option"><b>${k}.</b> ${esc(a.x.options[k])}</div>`).join('')}<p class="small">Answer: ${a.x.correctAnswer}</p></div>`).join('')||'<p class="success">Nothing due.</p>'}</section>`;}

for(const b of document.querySelectorAll('nav button'))b.onclick=()=>go(b.dataset.view);render();
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();window.__install=e;$('#installBtn').classList.remove('hidden');$('#installBtn').onclick=()=>window.__install?.prompt()});
if(location.protocol!=='file:' && 'serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
// Keep the selected PDF only for the active import session so OCR can revisit pages without uploading/storing the PDF.
const originalHandle=handleSource;
async function wrappedSource(e){if(e.target.files[0]?.name.toLowerCase().endsWith('.pdf'))window.__lastPDFFile=e.target.files[0];return originalHandle(e)}
window.__lastPDFFile=null;
